@dataclass
class RiderGeofencingGpsEntity21:
    """Data transfer object for Delivery Rider Live GPS Geofencing and ETA Calculation - Segment 21."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    restaurant_code: str = "REST-IND-001"
